{
  "tasks": [
    {
      "task_id": "T01",
      "title": "一组与三组团队响应分钟中位数升序排名",
      "business_question": "在只看一组与三组的条件下，各团队的响应分钟中位数是多少？请按中位数升序排名。",
      "priority": "P0",
      "priority_reason": "删除后无法回答核心问题（按团队计算响应分钟中位数并升序排名），也不支持相关决策。该任务直接覆盖所有核心需求：C01（计算并排名）、C02（筛选一组与三组）、C03（指标为中位数）、C04（排序为升序）。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0002",
                "operator": "in",
                "value": [
                  "一组",
                  "三组"
                ]
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "median",
                "field": "field_0005",
                "alias": "response_median"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S03",
          "operation": "sort",
          "params": {
            "field": "response_median",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}
